WITH valid AS (SELECT *, ROUND(sqft * 1.1, 2) AS sqft_scaled, COALESCE(region, 'UNKNOWN') AS region_filled FROM stores WHERE region IS NOT NULL AND region = 'East') SELECT CASE WHEN sqft_scaled >= 65 THEN 'LARGE' ELSE 'SMALL' END AS sqft_scaled_tier, SORT_ARRAY(COLLECT_SET(city)) AS city_list, ROUND(SUM(sqft) / NULLIF(COUNT(CASE WHEN region = 'East' THEN 1 END), 0), 2) AS sqft_per_east FROM valid GROUP BY CASE WHEN sqft_scaled >= 65 THEN 'LARGE' ELSE 'SMALL' END
